 "content": "from collections import Counter

def transform(grid):
    counts = Counter(v for row in grid for v in row)
    common = {c for c, _ in counts.most_common(2)}
    markers = {(r, c): v
               for r, row in enumerate(grid)
               for c, v in enumerate(row)
               if v not in common}
    if not markers:
        return []
    ys = sorted({r for r, c in markers})
    xs = sorted({c for r, c in markers})
    background = counts.most_common(1)[0][0]
    out = [[background for _ in range(len(xs) - 1)]
           for _ in range(len(ys) - 1)]
    for i in range(len(ys) - 1):
        for j in range(len(xs) - 1):
            corners = [markers.get((ys[i], xs[j])),
                       markers.get((ys[i], xs[j + 1])),
                       markers.get((ys[i + 1], xs[j])),
                       markers.get((ys[i + 1], xs[j + 1]))]
            if corners[0] is not None and corners.count(corners[0]) == 4:
                out[i][j] = corners[0]
    return out
